const practiceLabels={unknown:"Пока неизвестно",none:"Не практикует",sometimes:"Практикует иногда",sessions_only:"Практикует иногда",daily:"Практикует каждый день",home_regular:"Практикует каждый день",twice_daily:"Практикует каждый день дважды",twice_daily_initiation:"Каждый день дважды, хочет инициацию"},sourceLabels={unknown:"Не указано",meditation_lessons:"Проект «Уроки медитации»",vk:"Группа ВКонтакте",avito:"Авито",marg:"Порекомендовал Марг",subscriber:"Порекомендовал подписчик",other:"Другое"},contactLabels={message:"Написали",call:"Позвонили",meeting:"Личная встреча",material:"Отправили материал"},weekdays=[["Пн",1],["Вт",2],["Ср",3],["Чт",4],["Пт",5],["Сб",6],["Вс",0]];
const journeyStages=[
 {id:"chat",title:"Приглашение в чат",wait:"Доступно после второго визита",steps:[{key:"chat_invited",label:"Пригласили",next:"пригласить в чат"},{key:"chat_joined",label:"Добавлен",next:"добавить в чат"}]},
 {id:"book",title:"Книга",steps:[{key:"book_acquired",label:"Приобрёл книгу",next:"предложить книгу"}]},
 {id:"basic",title:"Базовый курс",steps:[{key:"basic_started",label:"Начал",next:"предложить базовый курс"},{key:"basic_completed",label:"Завершил",next:"помочь завершить базовый курс"}]},
 {id:"kdi",title:"К-Д-И",steps:[{key:"kdi_started",label:"Начал",next:"предложить К-Д-И"},{key:"kdi_completed",label:"Завершил",next:"помочь завершить К-Д-И"}]},
 {id:"practice",title:"Регулярная практика",steps:[{key:"twice_daily",label:"Медитирует дважды в день",auto:true}]},
 {id:"curator",title:"Куратор",steps:[{key:"curator_offered",label:"Предложили",next:"предложить куратора"},{key:"curator_assigned",label:"Назначен",next:"назначить куратора"}]},
 {id:"acharya",title:"Знакомство с ачарьей",steps:[{key:"acharya_offered",label:"Предложили",next:"предложить знакомство с ачарьей"},{key:"acharya_met",label:"Познакомился",next:"организовать знакомство с ачарьей"}]},
 {id:"retreat",title:"Ретрит",steps:[{key:"retreat_invited",label:"Пригласили",next:"пригласить на ретрит"},{key:"retreat_attended",label:"Был на ретрите",next:"поддержать участие в ретрите"}]},
 {id:"mantra",title:"Получил мантру",steps:[{key:"mantra_received",label:"Получил",next:"обсудить получение мантры"}]},
 {id:"initiation",title:"Получил инициацию",important:true,steps:[{key:"initiation_received",label:"Получил",next:"поддержать путь к инициации"}]}
];
const journeyTotal=journeyStages.reduce((sum,stage)=>sum+stage.steps.length,0);
const achievementDone=(p,key)=>Boolean(p.achievements?.[key]);
function journeyProgress(p){return journeyStages.reduce((sum,stage)=>sum+stage.steps.filter(step=>achievementDone(p,step.key)).length,0)}
function journeyNext(p){for(const stage of journeyStages){if(stage.id==="chat"&&Number(p.visits)<2&&!stage.steps.every(step=>achievementDone(p,step.key)))return"После второго визита — пригласить в чат";for(const step of stage.steps)if(!step.auto&&!achievementDone(p,step.key))return step.next}return"Основные этапы пройдены"}
function journeyHint(p){return`Этапы ${journeyProgress(p)}/${journeyTotal} · Далее: ${journeyNext(p)}`}
function journeyDate(value){return value?new Date(value).toLocaleDateString("ru-RU",{day:"2-digit",month:"2-digit",year:"2-digit"}):""}
function renderJourney(p){const progress=journeyProgress(p),next=journeyNext(p);return`<details class="journey"><summary><div><b>Этапы пути</b><small>${h(next)}</small></div><span>${progress}/${journeyTotal}</span></summary><div class="journey-list">${journeyStages.map(stage=>{const ready=stage.id!=="chat"||Number(p.visits)>=2||stage.steps.some(step=>achievementDone(p,step.key));return`<div class="journey-row ${stage.important?"important":""} ${stage.steps.every(step=>achievementDone(p,step.key))?"done":""}"><div class="journey-label"><b>${stage.title}</b>${!ready&&stage.wait?`<small>${stage.wait}</small>`:""}</div><div class="journey-steps">${stage.steps.map(step=>{const done=achievementDone(p,step.key),disabled=step.auto||!ready,title=done?`Отмечено ${journeyDate(p.achievements[step.key])}`:step.auto?"Отмечается автоматически":"";return`<button type="button" class="journey-step ${done?"checked":""}" title="${h(title)}" ${disabled?"disabled":""} onclick="toggleAchievement(event,${p.id},'${step.key}')"><span>${done?"✓":""}</span>${step.label}</button>`}).join("")}</div></div>`}).join("")}</div></details>`}
async function toggleAchievement(event,id,key){event.stopPropagation();const p=state.people.find(x=>Number(x.id)===Number(id));if(!p)return;const completed=!achievementDone(p,key),button=event.currentTarget,keepOpen=$("#profile .journey")?.open??false;button.disabled=true;try{await request(`/api/people/${id}/achievement`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({key,completed})});p.achievements=p.achievements||{};if(completed)p.achievements[key]=new Date().toISOString();else delete p.achievements[key];renderPeople();await showProfile(id);const journey=$("#profile .journey");if(journey)journey.open=keepOpen;toast(completed?"Этап отмечен":"Отметка снята")}catch(error){button.disabled=false;toast(friendlyError(error))}}


const careStateLabels={new:"Новый",first_visit:"Первое посещение",active:"Активный",dropping:"Начал выпадать",dropped:"Выпал",returned:"Вернулся",repeat_dropout:"Повторно выпал",inactive:"Неактивный",invite_only:"Приглашать по подходящему поводу"};
const careEventLabels={first_message:"Написал впервые",invited:"Приглашён",confirmed:"Подтвердил участие",missed:"Пропустил",message_sent:"Сообщение отправлено",answered:"Ответил",absence_reason:"Причина отсутствия",feedback:"Обратная связь",review:"Отзыв",wants_continue:"Хочет продолжать",not_now:"Пока не хочет",next_step:"Следующий шаг",reactivation:"Реактивация",diagnostic_contact:"Диагностический контакт",profile_updated:"Данные заботы обновлены",other:"Другое"};
const barrierLabels={work:"Работа",time:"Неудобное время",family:"Семья",health:"Здоровье",meditation_hard:"Сложно медитировать",motivation:"Нет мотивации",forgets:"Забывает",distance:"Далеко ехать",finance:"Финансовые причины",format:"Не понял формат",self_practice:"Хочет заниматься самостоятельно",no_interest:"Пока нет интереса",other:"Другое"};
const motivationLabels={calm:"Спокойствие",learn:"Научиться медитировать",spiritual:"Духовное развитие",philosophy:"Философия",community:"Общение",like_minded:"Поиск единомышленников",stress:"Работа со стрессом",discipline:"Дисциплина",personal:"Личный запрос",other:"Другое"};
const defaultCareTemplates={reminder:"Привет, [Имя]! Завтра снова встречаемся. Если будет возможность — приходи 😊 Планируешь быть?",review:"Очень рад твоим результатам 🙏 Если комфортно, можешь в 2–3 предложениях написать об опыте? Это поможет тем, кто пока сомневается.",new_contact:"Привет, [Имя]! Рад познакомиться 😊 Если будут вопросы о практике или ближайшей встрече — обязательно напиши.",feedback:"Привет, [Имя] 😊 Рад был познакомиться на занятии. Как тебе практика? Что больше всего откликнулось или запомнилось?",no_show:"Привет, [Имя]! Сегодня тебя не увидели, решил написать 😊 Всё хорошо? Получилось просто не выбраться?",first_absence:"Привет, [Имя]! Как у тебя дела? Давно не виделись на практике. Как сейчас вообще с медитацией? Есть желание продолжать?",second_absence:"Привет, [Имя] 😊 Вспомнил про тебя. Тебе в целом хотелось бы продолжить приходить или сейчас не очень получается по времени или состоянию?",reactivation:"Привет, [Имя]! Давно не виделись. На этой неделе снова будет практика. Если почувствуешь, что хочется вернуться — будем рады. Никаких проблем, что был перерыв 😊",returned:"Привет, [Имя]! Рад был снова тебя увидеть 😊 Как у тебя после занятия? Получается сейчас продолжать практику?",repeat_dropout:"Привет, [Имя]! Рад был тебя снова увидеть в прошлый раз. Как у тебя после занятия? Получается сейчас как-то продолжать практику?",diagnostic:"Привет, [Имя]! Хочу понять, чтобы лишний раз тебя не дёргать 😊 Тебе сейчас хочется продолжать, просто сложно встроить занятия в график, или практика пока отошла на второй план?",invite_only:"Привет, [Имя]! У нас скоро будет особая встреча. Вспомнил о тебе — если тема откликается, буду рад рассказать подробнее."};
const careCfg=()=>({feedbackHours:4,reminderHours:24,firstAbsenceDays:7,secondAbsenceDays:14,reactivationDays:30,activeReturnVisits:3,templates:{},...(state.careSettings||{})});
const careTemplate=(key,p)=>String(careCfg().templates?.[key]||defaultCareTemplates[key]||"").replaceAll("[Имя]",p.first||"");
function visitPattern(p){const dates=[...(p.visitDates||[])].map(x=>new Date(x)).filter(x=>!isNaN(x)).sort((a,b)=>a-b),cfg=careCfg();let returns=0,lastReturnIndex=-1;for(let i=1;i<dates.length;i++)if((dates[i]-dates[i-1])/DAY>=cfg.secondAbsenceDays){returns++;lastReturnIndex=i}return{dates,returns,lastReturnIndex,visitsAfterReturn:lastReturnIndex>=0?dates.length-lastReturnIndex:0}}
function computedCareState(p){if(p.careState&&p.careState!=="auto")return p.careState;const cfg=careCfg(),visits=Number(p.visits)||0,absence=visits?days(p.lastVisit):Infinity,pattern=visitPattern(p),latest=p.careEvents?.[0];if(latest?.type==="not_now")return"inactive";if(visits===0)return"new";if(pattern.returns){if(absence>=cfg.firstAbsenceDays&&pattern.visitsAfterReturn<=2)return"repeat_dropout";if(pattern.visitsAfterReturn<cfg.activeReturnVisits)return"returned"}if(absence>=cfg.reactivationDays&&p.careEvents?.some(e=>e.type==="reactivation"&&new Date(e.date)>new Date(p.lastVisit)))return"invite_only";if(absence>=cfg.secondAbsenceDays)return"dropped";if(absence>=cfg.firstAbsenceDays)return"dropping";if(visits===1)return"first_visit";return"active"}
const careStateInfo=p=>{const key=computedCareState(p);return{key,text:careStateLabels[key]||key}};
const latestCareEvent=(p,type)=>(p.careEvents||[]).find(e=>!type||e.type===type);
function taskSuppressed(p,key){const task=(p.careTasks||[]).find(t=>t.sourceKey===key);return Boolean(task&&(task.status==="completed"||task.snoozedUntil&&new Date(task.snoozedUntil)>new Date()))}
function buildRec(p,data){const baseDate=p.lastVisit||p.created,source="care:"+data.type+":"+new Date(baseDate).toISOString().slice(0,10);if(taskSuppressed(p,source))return null;return{...data,sourceKey:source,message:careTemplate(data.template,p)}}
function careRecommendation(p){const cfg=careCfg(),stateKey=computedCareState(p),absence=Number(p.visits)?days(p.lastVisit):0,lastVisit=new Date(p.lastVisit||p.created),lastContact=p.lastContact?new Date(p.lastContact):null,missed=latestCareEvent(p,"missed"),confirmed=latestCareEvent(p,"confirmed");
 if(p.careNextContactAt&&new Date(p.careNextContactAt)<=new Date())return buildRec(p,{type:"individual",category:"individual",priority:"high",title:"Индивидуальная задача",situation:p.careNextStep||"Наступила назначенная дата контакта",goal:"Выполнить ранее запланированный следующий шаг.",action:p.careNextStep||"Связаться лично",template:"first_absence"});
 if(stateKey==="inactive")return null;
 if(confirmed?.dueAt){const eventDate=new Date(confirmed.dueAt),hours=(eventDate-Date.now())/36e5,attended=Number(p.visits)>0&&new Date(p.lastVisit)>=eventDate;if(hours<0&&!attended)return buildRec(p,{type:"no_show",category:"missed",priority:"high",title:"Обещал прийти, но не пришёл",situation:"Подтверждённая встреча уже прошла, посещение не отмечено.",goal:"Проверить, всё ли хорошо, без требования объяснений.",action:"Написать лично",template:"no_show"});if(hours>=0&&hours<=cfg.reminderHours)return buildRec(p,{type:"reminder",category:"reminder",priority:"high",title:"Напомнить о встрече",situation:"Человек подтвердил участие, встреча скоро.",goal:"Мягко напомнить и помочь принять конкретное решение.",action:"Отправить напоминание",template:"reminder",dueAt:eventDate.toISOString()})}
 if(missed&&(!lastContact||lastContact<new Date(missed.date)))return buildRec(p,{type:"no_show",category:"missed",priority:"high",title:"Не пришёл после подтверждения",situation:"Человек собирался прийти, но посещение не состоялось.",goal:"Проверить, всё ли хорошо, без требования объяснений.",action:"Написать лично",template:"no_show"});
 if(stateKey==="new")return buildRec(p,{type:"new_contact",category:"new",priority:"high",title:"Новый человек",situation:"Контакт есть, посещений пока не было.",goal:"Ответить и создать спокойный первый контакт.",action:"Написать приветственное сообщение",template:"new_contact"});
 if(stateKey==="first_visit"&&!p.careEvents?.some(e=>e.type==="feedback"&&new Date(e.date)>lastVisit)){const due=new Date(lastVisit.getTime()+cfg.feedbackHours*36e5);return buildRec(p,{type:"feedback",category:"feedback",priority:"medium",title:"Получить обратную связь",situation:"Первое посещение уже состоялось.",goal:"Понять опыт, сложности и запрос человека.",action:due>new Date()?"Написать после "+due.toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"}):"Написать лично",template:"feedback",dueAt:due.toISOString()})}
 if(stateKey==="returned")return buildRec(p,{type:"return_followup",category:"returned",priority:"medium",title:"Поддержать возвращение",situation:"Человек вернулся после долгого перерыва.",goal:"Узнать состояние и помочь закрепить возвращение.",action:"Написать после занятия",template:"returned"});
 if(stateKey==="repeat_dropout"){const repeated=visitPattern(p).returns>1;return buildRec(p,{type:repeated?"diagnostic_contact":"repeat_dropout",category:"repeat_dropout",priority:"medium",title:"Повторное выпадение",situation:"После возвращения было только 1–2 посещения, затем снова перерыв.",goal:"Понять желание продолжать и реальное препятствие.",action:"Провести диагностический контакт",template:repeated?"diagnostic":"repeat_dropout"})}
 if(absence>=cfg.reactivationDays)return buildRec(p,{type:"reactivation",category:"reactivation",priority:"low",title:"Мягкая реактивация",situation:absence+" дней без посещений.",goal:"Оставить удобную возможность вернуться без давления.",action:"Написать один раз",template:"reactivation"});
 if(stateKey==="dropped")return buildRec(p,{type:"second_absence",category:"absence14",priority:"medium",title:"Понять препятствие",situation:absence+" дней без посещений.",goal:"Узнать желание продолжать и причину отсутствия.",action:"Написать лично",template:"second_absence"});
 if(stateKey==="dropping")return buildRec(p,{type:"first_absence",category:"absence7",priority:"medium",title:"Мягко восстановить контакт",situation:absence+" дней без посещений.",goal:"Понять текущее состояние, не убеждать и не контролировать.",action:"Написать лично",template:"first_absence"});
 if(stateKey==="invite_only")return buildRec(p,{type:"invite_only",category:"occasion",priority:"low",title:"Пригласить по подходящему поводу",situation:"Активная цепочка заботы завершена.",goal:"Предлагать только действительно подходящие события.",action:"Пригласить при релевантном событии",template:"invite_only"});
 if(stateKey==="active"&&Number(p.visits)>=3&&!p.careEvents?.some(e=>e.type==="review"))return buildRec(p,{type:"review",category:"feedback",priority:"low",title:"Можно запросить отзыв",situation:"У человека уже есть опыт нескольких посещений.",goal:"Получить добровольный короткий отзыв без давления.",action:"Предложить оставить отзыв",template:"review"});
 return null
}
function careRecommendations(){const weight={high:0,medium:1,low:2};return state.people.map(p=>({p,rec:careRecommendation(p)})).filter(x=>x.rec).sort((a,b)=>weight[a.rec.priority]-weight[b.rec.priority])}


function renderCareDashboard(){const filters=[["all","Все"],["new","Новые"],["feedback","Обратная связь"],["reminder","Напомнить"],["missed","Пропустили"],["absence7","7 дней"],["absence14","14 дней"],["repeat_dropout","Повторно выпали"],["reactivation","Реактивация"],["individual","Индивидуальные"]],all=careRecommendations(),list=careFilter==="all"?all:all.filter(x=>x.rec.category===careFilter);$("#careFilters").innerHTML=filters.map(([key,label])=>'<button class="'+(careFilter===key?"active":"")+'" onclick="setCareFilter(\''+key+'\')">'+label+"<span>"+(key==="all"?all.length:all.filter(x=>x.rec.category===key).length)+"</span></button>").join("");$("#careTaskList").innerHTML=list.map(({p,rec})=>`<article class="care-task card priority-${rec.priority}"><header><div class="care-person">${p.photoUrl?`<img src="${h(p.photoUrl)}" alt="">`:`<div class="av ${av(p.id)}">${initials(p)}</div>`}<div><h3>${h(p.first)} ${h(p.last||"")}</h3><span class="care-state">${careStateInfo(p).text}</span></div></div><span class="priority-badge">${rec.priority==="high"?"Высокий":rec.priority==="medium"?"Средний":"Низкий"}</span></header><div class="care-context"><p><b>Ситуация:</b> ${h(rec.situation)}</p><p><b>Цель:</b> ${h(rec.goal)}</p><p><b>Действие:</b> ${h(rec.action)}</p>${p.careMotivations?.length?`<p><b>Важно:</b> ${p.careMotivations.map(x=>motivationLabels[x]||x).join(", ")}</p>`:""}${p.careBarriers?.length?`<p><b>Препятствие:</b> ${p.careBarriers.map(x=>barrierLabels[x]||x).join(", ")}</p>`:""}</div><blockquote>${h(rec.message)}</blockquote><details class="care-guidance"><summary>Почему мы пишем и чего избегать</summary><p>${h(rec.goal)}</p><p>Не требовать объяснений, не стыдить и не писать несколько раз подряд.</p></details><footer><button onclick="copyCareMessage(${p.id})">Скопировать</button>${messengerButtons(p)}<button onclick="startCareContact(${p.id})">Написал</button><button onclick="postponeCare(${p.id})">Отложить</button><button onclick="editCareMessage(${p.id})">Изменить текст</button><button onclick="openPersonFromCare(${p.id})">Карточка</button></footer></article>`).join("")||'<article class="card empty">На сегодня активных задач нет</article>'}
function setCareFilter(key){careFilter=key;renderCareDashboard()}window.setCareFilter=setCareFilter;
async function copyText(text,notice="Сообщение скопировано"){try{await navigator.clipboard.writeText(text)}catch{const area=document.createElement("textarea");area.value=text;document.body.append(area);area.select();document.execCommand("copy");area.remove()}toast(notice)}
const recFor=id=>{const p=state.people.find(x=>Number(x.id)===Number(id));return p?{p,rec:careRecommendation(p)}:null};
function copyCareMessage(id){const item=recFor(id);if(item?.rec)copyText(item.rec.message)}window.copyCareMessage=copyCareMessage;
function editCareMessage(id){const item=recFor(id);if(!item?.rec)return;const text=prompt("Измените текст перед копированием",item.rec.message);if(text!==null)copyText(text,"Изменённый текст скопирован")}window.editCareMessage=editCareMessage;
function startCareContact(id){const item=recFor(id);if(!item?.rec)return;pendingCareRecommendation=item.rec;openContact(id)}window.startCareContact=startCareContact;
async function postponeCare(id){const item=recFor(id);if(!item?.rec)return;const count=Number(prompt("На сколько дней отложить?","7"));if(!count||count<1)return;try{await request("/api/care/tasks/"+id,{method:"POST",body:JSON.stringify({sourceKey:item.rec.sourceKey,taskType:item.rec.type,priority:item.rec.priority,status:"snoozed",snoozedUntil:new Date(Date.now()+count*DAY).toISOString()})});toast("Задача отложена");await load()}catch(error){toast(friendlyError(error))}}window.postponeCare=postponeCare;
function openPersonFromCare(id){go("people");showProfile(id)}window.openPersonFromCare=openPersonFromCare;
