function openCareProfile(id){const p=state.people.find(x=>Number(x.id)===Number(id));if(!p)return;$("#careProfilePersonId").value=id;$("#careProfilePerson").textContent=p.first;$("#careManualState").value=p.careState||"auto";$("#careBarriers").innerHTML=optionChecks(barrierLabels,p.careBarriers||[]);$("#careMotivations").innerHTML=optionChecks(motivationLabels,p.careMotivations||[]);$("#careNote").value=p.careNote||"";$("#careNextStep").value=p.careNextStep||"";$("#careNextContactAt").value=p.careNextContactAt?new Date(p.careNextContactAt).toISOString().slice(0,10):"";$("#careProfileDialog").showModal()}window.openCareProfile=openCareProfile;
