function renderCareSettings(){const box=$("#careSettings");if(!box)return;const c=careCfg(),templates={...defaultCareTemplates,...(c.templates||{})},fields=[["feedback","После первого занятия"],["first_absence","7 дней"],["second_absence","14 дней"],["reactivation","Реактивация"],["repeat_dropout","Повторное выпадение"],["diagnostic","Диагностический контакт"]];box.innerHTML=`<article class="card care-settings-card"><h2>Настройки заботы</h2><div class="care-settings-grid"><label>Обратная связь через, часов<input id="setFeedbackHours" type="number" min="1" max="48" value="${c.feedbackHours}"></label><label>Напоминание заранее, часов<input id="setReminderHours" type="number" min="1" max="72" value="${c.reminderHours}"></label><label>Первое отсутствие, дней<input id="setFirstAbsence" type="number" min="1" max="60" value="${c.firstAbsenceDays}"></label><label>Выпадение, дней<input id="setSecondAbsence" type="number" min="2" max="120" value="${c.secondAbsenceDays}"></label><label>Реактивация, дней<input id="setReactivation" type="number" min="7" max="365" value="${c.reactivationDays}"></label><label>Посещений для возврата<input id="setReturnVisits" type="number" min="2" max="10" value="${c.activeReturnVisits}"></label></div><details><summary>Тексты сообщений</summary><div class="template-grid">${fields.map(([key,label])=>`<label>${label}<textarea data-care-template="${key}">${h(templates[key])}</textarea></label>`).join("")}</div></details><button class="primary" onclick="saveCareSettings()">Сохранить настройки</button></article>`}
