function datesAroundToday(weekday){const today=new Date();today.setHours(0,0,0,0);const start=new Date(today);start.setDate(start.getDate()-7);const end=new Date(today);end.setDate(end.getDate()+7);const dates=[];for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1))if(d.getDay()===weekday){const occurrence=new Date(d);occurrence.setHours(18,0,0,0);dates.push(occurrence)}return dates}
