async function dismissScheduled(event,encodedTitle,date,cityId){event.stopPropagation();const title=decodeURIComponent(encodedTitle),label=new Date(date).toLocaleDateString("ru-RU",{day:"numeric",month:"long"});if(!confirm(`Отметить, что встреча «${title}» ${label} не состоялась?`))return;event.currentTarget.disabled=true;try{await request("/api/schedules/dismiss",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({cityId,title,date})});state.dismissedSchedules=state.dismissedSchedules||[];state.dismissedSchedules.push({cityId:Number(cityId),eventType:title,date});renderUpcoming();toast("Встреча убрана с главного экрана")}catch(error){event.currentTarget.disabled=false;toast(friendlyError(error))}}
