async function showProfile(id){const p=state.people.find(x=>Number(x.id)===Number(id));if(!p)return;const status=attendanceStatus(p),careState=careStateInfo(p),rec=careRecommendation(p),mark=contactMark(p),lastContact=p.lastContact?`Последний контакт: ${new Date(p.lastContact).toLocaleDateString("ru-RU")}`:"Контакт ещё не зафиксирован",motives=(p.careMotivations||[]).map(x=>motivationLabels[x]||x),barriers=(p.careBarriers||[]).map(x=>barrierLabels[x]||x);$("#profile").innerHTML=`<button class="x" onclick="profileDialog.close()">×</button><div class="profile-title">${p.photoUrl?`<img class="profile-photo" src="${h(p.photoUrl)}" alt="">`:`<div class="av big ${av(p.id)}">${initials(p)}</div>`}<div><h2>${h(p.first)} ${h(p.last||"")}</h2><p>${h(cityName(p.cityId))} · ${h(p.contact||"Контакт не указан")}</p></div></div><div class="status-pair"><span class="status care-status">${careState.text}</span><span class="status ${status.cls}">${status.text}</span><span class="status practice">${practiceLabels[p.practiceStatus]||practiceLabels.unknown}</span></div>${Number(p.visits)>0?`<div class="absence-card"><b>${days(p.lastVisit)} дней</b><span>с последнего занятия</span></div>`:""}${rec?`<section class="recommended-action priority-${rec.priority}"><small>Рекомендуемое действие</small><h3>${h(rec.title)}</h3><p><b>Ситуация:</b> ${h(rec.situation)}</p><p><b>Цель:</b> ${h(rec.goal)}</p><p><b>Что сделать:</b> ${h(rec.action)}</p><blockquote>${h(rec.message)}</blockquote><div class="recommended-buttons"><button onclick="copyCareMessage(${p.id})">Скопировать сообщение</button><button class="primary" onclick="startCareContact(${p.id})">Написал</button><button onclick="postponeCare(${p.id})">Отложить</button><button onclick="editCareMessage(${p.id})">Изменить текст</button><button onclick="stopActiveCare(${p.id})">Не связываться</button><button onclick="openCareEvent(${p.id})">Другое действие</button></div><details><summary>Почему мы пишем?</summary><p>${h(rec.goal)}</p><p>Не требовать объяснений, не стыдить и не создавать ощущение контроля.</p></details></section>`:""}<div class="profile-stat-grid"><div><strong>${Number(p.visits)||0}</strong><span>всего посещений</span></div><div><strong>${Number(p.recentVisits)||0}</strong><span>за последние 30 дней</span></div><div><strong>${Number(p.contactCount)||0}</strong><span>зафиксировано контактов</span></div></div>${renderJourney(p)}<section class="profile-section care-person-section"><div class="section-title"><h3>Контекст заботы</h3><button onclick="openCareProfile(${p.id})">Редактировать</button></div><div class="care-facts"><div><span>Что важно</span><b>${h(motives.join(", ")||"Пока не указано")}</b></div><div><span>Причины и препятствия</span><b>${h(barriers.join(", ")||"Пока не указано")}</b></div><div><span>Следующий шаг</span><b>${h(p.careNextStep||"Не назначен")}</b></div></div>${p.careNote?`<p class="care-note">${h(p.careNote)}</p>`:""}<div class="care-log-buttons"><button onclick="openCareEvent(${p.id},'feedback')">＋ Обратная связь</button><button onclick="openCareEvent(${p.id},'review')">＋ Отзыв</button><button onclick="openCareEvent(${p.id})">＋ Событие</button></div></section><section class="profile-section"><h3>О человеке</h3><div class="profile-facts"><div><span>Откуда узнал</span><b>${sourceLabels[p.source]||sourceLabels.unknown}</b></div><div><span>Познакомились</span><b>${new Date(p.acquaintanceDate||p.created).toLocaleDateString("ru-RU")}</b></div></div><div class="profile-note"><span>Комментарий</span><p>${h(p.note||"Комментариев пока нет")}</p></div></section><section class="profile-section profile-history-card"><h3>Хронология</h3><div id="personHistory" class="history"><span>Загружаем…</span></div></section><div class="contact-summary ${mark.cls}"><b>${mark.text}</b><span>${lastContact}</span></div><footer class="profile-actions"><button onclick="message(${p.id})">Скопировать сообщение</button>${p.contact?`<button onclick="openContactLink(${p.id})">Открыть контакт</button>`:""}<button class="primary" onclick="openContact(${p.id})">Зафиксировать контакт</button></footer>`;if(!$("#profileDialog").open)$("#profileDialog").showModal();try{const history=await request(`/api/people/${id}/history`),all=[...history.visits.map(v=>({date:v.date,title:"Посетил: "+v.title,kind:"visit",meta:""})),...history.contacts.map(c=>({date:c.date,title:(contactLabels[c.type]||"Контакт")+(c.note?": "+c.note:""),kind:"contact",meta:c.author||""})),...(history.careEvents||[]).filter(e=>e.type!=="profile_updated").map(e=>({date:e.date,title:(careEventLabels[e.type]||e.type)+(e.comment?": "+e.comment:""),kind:"care",meta:[e.result,e.state?careStateLabels[e.state]||e.state:"",e.author].filter(Boolean).join(" · ")}))].sort((a,b)=>new Date(b.date)-new Date(a.date));$("#personHistory").innerHTML=all.map(x=>`<div class="history-item ${x.kind}"><time>${new Date(x.date).toLocaleDateString("ru-RU",{day:"numeric",month:"short",year:"numeric"})}</time><div><b>${h(x.title)}</b>${x.meta?`<small>${h(x.meta)}</small>`:""}</div></div>`).join("")||"<span>История пока пустая</span>"}catch{$("#personHistory").textContent="Не удалось загрузить историю"}}
const showProfileBase=showProfile;
showProfile=function(id){const pending=showProfileBase(id);requestAnimationFrame(()=>{const p=state.people.find(x=>Number(x.id)===Number(id)),footer=$("#profile .profile-actions");if(!p||!footer||footer.querySelector(".messenger-links"))return;const copyButton=footer.querySelector("button");copyButton?.insertAdjacentHTML("afterend",messengerButtons(p))});return pending};window.showProfile=showProfile;
async function message(id){const p=state.people.find(x=>Number(x.id)===Number(id));if(!p)return;const rec=careRecommendation(p),text=rec?.message||`${p.first}, здравствуйте! Как вы? Хотелось узнать, всё ли хорошо и можем ли мы чем-то помочь?`;copyText(text,"Заботливое сообщение скопировано")}window.message=message;
function openContact(id){const p=state.people.find(x=>Number(x.id)===Number(id)),rec=pendingCareRecommendation||careRecommendation(p);$("#contactPersonId").value=id;$("#contactPerson").textContent=`${p.first} ${p.last||""}`;$("#contactNote").value="";$("#contactResult").value="answered";$("#contactNextStep").value="";$("#contactNextDate").value="";$("#contactTaskKey").value=rec?.sourceKey||"";$("#contactEventType").value=rec?.type==="reactivation"?"reactivation":rec?.type==="diagnostic_contact"?"diagnostic_contact":rec?.type==="feedback"?"feedback":"message_sent";pendingCareRecommendation=null;$("#profileDialog").close();$("#contactDialog").showModal()}window.openContact=openContact;
function messengerTargets(person){const raw=String(person?.contact||"").trim(),targets={};if(!raw)return targets;let match=raw.match(/(?:https?:\/\/)?(?:t\.me|telegram\.me)\/([a-z0-9_]{3,})/i);if(!match)match=raw.match(/(?:^|\s)@([a-z0-9_]{3,})(?:\s|$)/i);if(match)targets.telegram={url:"https://t.me/"+match[1],label:"Telegram"};match=raw.match(/(?:https?:\/\/)?(?:m\.)?vk\.com\/([a-z0-9_.-]+)/i);if(match&&!/^(?:im|feed|wall|share)$/i.test(match[1]))targets.vk={url:"https://vk.me/"+match[1],label:"ВКонтакте"};match=raw.match(/https?:\/\/(?:www\.)?max\.ru\/[^\s]+/i);if(match)targets.max={url:match[0],label:"MAX"};const phone=raw.match(/\+?[\d\s()\-]{7,}/)?.[0]?.replace(/[^+\d]/g,"");if(!targets.max&&phone)targets.max={url:"https://max.ru/",label:"MAX",phone};return targets}
function messengerButtons(person){const targets=messengerTargets(person),items=[targets.telegram&&["telegram","TG","Telegram"],targets.vk&&["vk","VK","ВКонтакте"],targets.max&&["max","M","MAX"]].filter(Boolean);if(!items.length)return"";return`<span class="messenger-links" aria-label="Открыть мессенджер">${items.map(([key,short,label])=>`<button type="button" class="messenger-link ${key}" title="Открыть ${label}" aria-label="Открыть ${label}" onclick="event.stopPropagation();openMessenger(${person.id},'${key}')"><span aria-hidden="true">${short}</span></button>`).join("")}</span>`}
function openMessenger(id,type){const p=state.people.find(x=>Number(x.id)===Number(id)),target=messengerTargets(p)[type];if(!target){toast("Ссылка на этот мессенджер не указана");return}if(type==="max"&&target.phone){copyText(target.phone,"Номер скопирован — выберите контакт в MAX");window.open(target.url,"_blank","noopener");return}window.open(target.url,"_blank","noopener")}window.openMessenger=openMessenger;
function openContactLink(id){const p=state.people.find(x=>Number(x.id)===Number(id)),raw=String(p?.contact||"").trim();if(!raw){toast("Контакт не указан");return}const targets=messengerTargets(p),target=targets.telegram||targets.vk||targets.max;let url=target?.url||"";if(!url&&/^https?:\/\//i.test(raw))url=raw;else if(!url&&/^\+?[\d\s()\-]{7,}$/.test(raw))url="tel:"+raw.replace(/[^+\d]/g,"");if(url){window.open(url,"_blank","noopener")}else{navigator.clipboard?.writeText(raw);toast("Контакт скопирован")}}window.openContactLink=openContactLink;
async function visited(id){await request(`/api/people/${id}/visit`,{method:"POST",body:"{}"});$("#profileDialog").close();toast("Посещение отмечено");await load()}window.visited=visited;
function setVisitDate(date){const value=new Date(date);$("#visitDateInput").value=[value.getFullYear(),String(value.getMonth()+1).padStart(2,"0"),String(value.getDate()).padStart(2,"0")].join("-");$("#visitDate").textContent=value.toLocaleDateString("ru-RU",{weekday:"long",day:"numeric",month:"long"})}

const meetingTypes=["Коллективная медитация","Карма-йога","Лекция","Дхармадеха"];
function setVisitType(title){const select=$("#visitType"),custom=$("#visitCustomType"),known=meetingTypes.includes(title);select.value=known?title:"Другое";custom.hidden=known;custom.value=known?"":title==="Другое"?"":title;pendingEvent.title=title}
function syncVisitType(){const custom=$("#visitCustomType").value.trim(),type=$("#visitType").value;pendingEvent.title=type==="Другое"?(custom||"Другое"):type;return pendingEvent.title}
function openAttendance(title="Коллективная медитация",date=new Date().toISOString(),cityId=currentCity||state.user.cityId){if(!cityId){toast("Сначала выберите город");$("#city").focus();return}pendingEvent={title,eventDate:date,cityId:Number(cityId),note:""};attendanceSelected=new Set();attendanceExisting=new Set();$("#attendanceSearch").value="";$("#visitNote").value="";$("#visitDateInput").disabled=false;$("#visitType").disabled=false;$("#visitCustomType").disabled=false;setVisitType(title);$("#visitTitle").textContent="Новая встреча";setVisitDate(date);renderChecks();$("#visitDialog").showModal()}window.openAttendance=openAttendance;
function toggleEventMenu(e,id){e.stopPropagation();const menu=$("#event-menu-"+id),opening=menu.hidden;$$(".event-menu").forEach(x=>x.hidden=true);$$(".event-more").forEach(x=>x.setAttribute("aria-expanded","false"));menu.hidden=!opening;e.currentTarget.setAttribute("aria-expanded",String(opening))}window.toggleEventMenu=toggleEventMenu;
