async function editEvent(id){try{const data=await request(`/api/events/${id}`);pendingEvent={id:data.event.id,title:data.event.title,eventDate:data.event.date,cityId:Number(data.event.cityId),note:data.event.note||""};attendanceExisting=new Set(data.personIds.map(Number));attendanceSelected=new Set(data.personIds.map(Number));$("#attendanceSearch").value="";$("#visitNote").value=data.event.note||"";$("#visitDateInput").disabled=false;$("#visitType").disabled=false;$("#visitCustomType").disabled=false;setVisitType(data.event.title);$("#visitTitle").textContent="Редактировать встречу";setVisitDate(data.event.date);renderChecks();$("#visitDialog").showModal()}catch(error){toast(friendlyError(error))}}window.editEvent=editEvent;
async function showEventAttendees(e,id,kind){e.stopPropagation();try{const data=await request(`/api/events/${id}`),labels={all:"Все участники",new:"Новенькие",repeat:"Пришли повторно"},list=data.attendees.filter(p=>kind==="all"||(kind==="new"?Number(p.isNew)===1:Number(p.isNew)!==1));$("#attendeeDetailsTitle").textContent=labels[kind];$("#attendeeDetailsMeta").textContent=`${data.event.title} · ${new Date(data.event.date).toLocaleDateString("ru-RU",{day:"numeric",month:"long",year:"numeric"})}`;$("#attendeeDetailsList").innerHTML=list.map(p=>`<div class="attendee-row"><div class="av ${av(p.id)}">${initials(p)}</div><span><b>${p.first} ${p.last||""}</b><small>${Number(p.isNew)===1?"Первое посещение":"Повторное посещение"}</small></span></div>`).join("")||'<div class="empty">В этой категории никого нет</div>';$("#attendanceDetailsDialog").showModal()}catch(error){toast(friendlyError(error))}}window.showEventAttendees=showEventAttendees;
