function openAddPerson(cityId=currentCity,fromAttendance=false){if(!cityId){toast("Сначала выберите город");$("#city").focus();return}editingPersonId=null;addingFromAttendance=fromAttendance;$("#addForm").reset();$("#addForm h2").textContent="Новый человек";$("#newCity").value=String(cityId);$("#acquaintanceDate").value=fromAttendance?$("#visitDateInput").value:new Date().toISOString().slice(0,10);if(fromAttendance)$("#visitDialog").close();$("#addDialog").showModal();setTimeout(()=>$("#first").focus(),0)}
function editPerson(e,id){e.stopPropagation();const p=state.people.find(x=>Number(x.id)===Number(id));if(!p)return;editingPersonId=Number(id);addingFromAttendance=false;$("#addForm").reset();$("#addForm h2").textContent="Редактировать человека";$("#first").value=[p.first,p.last].filter(Boolean).join(" ");$("#contact").value=p.contact||"";$("#newCity").value=String(p.cityId);$("#acquaintanceDate").value=(p.acquaintanceDate||p.created||"").slice(0,10);$("#source").value=p.source||"unknown";$("#photoUrl").value=p.photoUrl||"";$("#practiceStatus").value=["sessions_only","home_regular"].includes(p.practiceStatus)?(p.practiceStatus==="sessions_only"?"sometimes":"daily"):(p.practiceStatus||"unknown");$("#note").value=p.note||"";$("#addDialog").showModal()}window.editPerson=editPerson;
