$$("[data-add]").forEach(b=>b.onclick=()=>openAddPerson(currentCity,false));$$("[data-attendance]").forEach(b=>b.onclick=()=>openAttendance());$$("[data-close]").forEach(b=>b.onclick=()=>b.closest("dialog").close());$$("[data-close-add]").forEach(b=>b.onclick=closeAddPerson);
$("#addForm").onsubmit=async e=>{e.preventDefault();const submit=e.submitter||e.target.querySelector('button[type="submit"]');submit.disabled=true;try{const payload={first:$("#first").value.trim(),last:"",contact:$("#contact").value.trim(),note:$("#note").value.trim(),photoUrl:$("#photoUrl").value.trim(),practiceStatus:$("#practiceStatus").value,cityId:Number($("#newCity").value),acquaintanceDate:$("#acquaintanceDate").value||new Date().toISOString().slice(0,10),source:$("#source").value};const isEdit=Boolean(editingPersonId),result=await request(isEdit?`/api/people/${editingPersonId}`:"/api/people/new",{method:isEdit?"PATCH":"POST",body:JSON.stringify(payload)}),reopen=!isEdit&&addingFromAttendance;addingFromAttendance=false;editingPersonId=null;if(reopen)attendanceSelected.add(Number(result.id));e.target.reset();$("#addDialog").close();toast(isEdit?"Карточка обновлена":reopen?"Новый участник добавлен и отмечен":"Человек добавлен");await load(currentCity);if(reopen){renderChecks();$("#visitDialog").showModal()}}catch(err){toast(friendlyError(err))}finally{submit.disabled=false}};
$("#contactForm").onsubmit=async e=>{e.preventDefault();const id=$("#contactPersonId").value,result=$("#contactResult").value,nextStep=$("#contactNextStep").value;let nextContactAt=$("#contactNextDate").value?new Date($("#contactNextDate").value+"T12:00:00").toISOString():null;if(!nextContactAt&&nextStep==="write_week")nextContactAt=new Date(Date.now()+7*DAY).toISOString();if(!nextContactAt&&nextStep==="write_two_weeks")nextContactAt=new Date(Date.now()+14*DAY).toISOString();const state=result==="not_now"||nextStep==="inactive"?"inactive":nextStep==="invite_only"?"invite_only":"";try{await request(`/api/people/${id}/contact`,{method:"POST",body:JSON.stringify({type:$("#contactType").value,note:$("#contactNote").value,result,nextStep:nextStepLabels[nextStep]||nextStep,nextContactAt,state,eventType:$("#contactEventType").value||"message_sent",sourceKey:$("#contactTaskKey").value})});$("#contactDialog").close();toast("Контакт и следующий шаг сохранены");await load()}catch(err){toast(friendlyError(err))}};
$("#careProfileForm").onsubmit=async e=>{e.preventDefault();const id=Number($("#careProfilePersonId").value),barriers=$("#careBarriers input:checked").map(x=>x.value),motivations=$("#careMotivations input:checked").map(x=>x.value);try{await request("/api/care/profile/"+id,{method:"PATCH",body:JSON.stringify({state:$("#careManualState").value,barriers,motivations,note:$("#careNote").value.trim(),nextStep:$("#careNextStep").value.trim(),nextContactAt:$("#careNextContactAt").value?new Date($("#careNextContactAt").value+"T12:00:00").toISOString():null})});$("#careProfileDialog").close();toast("Данные заботы сохранены");await load();showProfile(id)}catch(error){toast(friendlyError(error))}};
$("#careEventForm").onsubmit=async e=>{e.preventDefault();const personId=Number($("#careEventPersonId").value),eventType=$("#careEventType").value,state=eventType==="not_now"?"inactive":"",dueAt=$("#careEventDueAt").value?new Date($("#careEventDueAt").value+"T12:00:00").toISOString():null;try{await request("/api/care/events",{method:"POST",body:JSON.stringify({personId,eventType,comment:$("#careEventComment").value.trim(),result:$("#careEventResult").value.trim(),state,nextStep:$("#careEventNextStep").value.trim(),dueAt})});$("#careEventDialog").close();toast("Событие добавлено в хронологию");await load();showProfile(personId)}catch(error){toast(friendlyError(error))}};

$("#saveVisit").onclick=async()=>{const ids=[...attendanceSelected];syncVisitType();pendingEvent.note=$("#visitNote").value.trim();try{if(pendingEvent.id){await request(`/api/events/${pendingEvent.id}`,{method:"PATCH",body:JSON.stringify({...pendingEvent,personIds:ids})});toast("Встреча обновлена")}else{await request("/api/events",{method:"POST",body:JSON.stringify({...pendingEvent,personIds:ids})});toast(`Отмечено участников: ${ids.length}`)}$("#visitDialog").close();await load()}catch(error){toast(friendlyError(error))}};
function exportExcel(){const rows=[["Имя","Город","Контакт","Состояние заботы","Статус посещений","Домашняя практика","Всего посещений","За 30 дней","Последнее занятие","Последний контакт","Причины / препятствия","Что важно","Следующий шаг","Комментарий заботы","Общий комментарий"],...state.people.map(p=>[p.first,cityName(p.cityId),p.contact,careStateInfo(p).text,attendanceStatus(p).text,practiceLabels[p.practiceStatus],p.visits,p.recentVisits,Number(p.visits)>0?new Date(p.lastVisit).toLocaleDateString("ru-RU"):"—",p.lastContact?new Date(p.lastContact).toLocaleDateString("ru-RU"):"—",(p.careBarriers||[]).map(x=>barrierLabels[x]||x).join(", "),(p.careMotivations||[]).map(x=>motivationLabels[x]||x).join(", "),p.careNextStep,p.careNote,p.note])],csv="\ufeff"+rows.map(r=>r.map(v=>`"${String(v||"").replaceAll('"','""')}"`).join(";")).join("\n"),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));a.download=`Ananda_Prachar_${cityName(currentCity)}_${new Date().toISOString().slice(0,10)}.csv`;a.click();toast("Файл сохранён в папку «Загрузки»")}
$("#exportPeople")?.addEventListener("click",exportExcel);$("#exportAnalytics")?.addEventListener("click",exportExcel);$("#logoutApp")?.addEventListener("click",async()=>{await request("/api/auth/logout",{method:"POST",body:"{}"});location.reload()});$("#teamAddCity")?.addEventListener("click",async()=>{const name=prompt("Название города или посёлка");if(!name?.trim())return;try{const result=await request("/api/cities",{method:"POST",body:JSON.stringify({name:name.trim()})});currentCity=String(result.id);await request("/api/me/preferences",{method:"PATCH",body:JSON.stringify({cityId:result.id})});toast("Населённый пункт добавлен");await load(currentCity)}catch(e){toast(friendlyError(e))}});$$("[data-period]").forEach(b=>b.onclick=()=>{$$("[data-period]").forEach(x=>x.classList.remove("active"));b.classList.add("active");period=Number(b.dataset.period);renderAnalytics()});
function renderPasswordUpdate(){document.body.innerHTML=`<main class="login"><div class="brand"><span class="brand-mark">AP</span><b>Ananda Prachar</b></div><h1>Новый пароль</h1><p class="lead">Придумайте новый пароль длиной не меньше 8 символов.</p><form id="passwordForm" class="auth-form"><label>Новый пароль<input id="newPassword" type="password" minlength="8" autocomplete="new-password" required></label><p id="authError" class="auth-error" hidden></p><button class="primary" type="submit">Сохранить пароль</button></form></main>`;$("#passwordForm").onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await request("/api/auth/password",{method:"PATCH",body:JSON.stringify({password:$("#newPassword").value})});document.querySelector(".lead").textContent="Пароль сохранён. Открываем приложение…";$("#passwordForm").hidden=true;history.replaceState(null,"",location.pathname);setTimeout(()=>location.reload(),900)}catch(error){$("#authError").textContent=friendlyError(error);$("#authError").hidden=false;button.disabled=false}}}
window.addEventListener("ananda-password-recovery",renderPasswordUpdate);
window.addEventListener("error",event=>{console.error("Ananda Prachar:",event.error||event.message)});
window.addEventListener("unhandledrejection",event=>{console.error("Ananda Prachar:",event.reason)});
function registerAgentTools(){const mc=document.modelContext;if(!mc?.registerTool)return;Promise.resolve(mc.registerTool({name:"add_person",title:"Добавить человека",description:"Добавляет человека в базу выбранного города.",inputSchema:{type:"object",properties:{first:{type:"string"},last:{type:"string"},contact:{type:"string"},note:{type:"string"},cityId:{type:"integer"}},required:["first","cityId"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){const result=await request("/api/people",{method:"POST",body:JSON.stringify(input)});await load();return{id:result.id,status:"created"}}})).catch(()=>{})}
let installPrompt=null;window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();installPrompt=event;$("#installApp").hidden=false});$("#installApp")?.addEventListener("click",async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$("#installApp").hidden=true}else toast("На iPhone: Поделиться → На экран Домой")});async function enableAutomaticUpdates(){if(!("serviceWorker" in navigator))return;let reloading=false;navigator.serviceWorker.addEventListener("controllerchange",()=>{if(reloading)return;reloading=true;location.reload()});try{const registration=await navigator.serviceWorker.register("./sw.js",{updateViaCache:"none"});await registration.update();setInterval(()=>registration.update().catch(()=>{}),30*60*1000);document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")registration.update().catch(()=>{})})}catch(error){console.warn("Не удалось проверить обновление приложения",error)}}const canonicalUrl=new URL(location.href);if(canonicalUrl.searchParams.has("v")){canonicalUrl.searchParams.delete("v");history.replaceState(null,"",canonicalUrl.pathname+(canonicalUrl.search||"")+(canonicalUrl.hash||""))}enableAutomaticUpdates();const firstView=location.hash.slice(1);if(firstView&&document.getElementById(firstView))go(firstView);registerAgentTools();if(window.authRecovery||location.hash.includes("type=recovery"))renderPasswordUpdate();else load();
